import { fetcher } from '../../../../assets/app/hooks/useFetch';

let getSettings = () => ( {} );
let initialized = false;

export const initSaveForm = ( settingsGetter ) => {
	getSettings = settingsGetter;

	if ( initialized ) {
		return;
	}
	initialized = true;

	const form = document.getElementById( 'post' );
	if ( !form ) {
		return;
	}

	// Force form to validate required fields.
	setTimeout( () => {
		form.removeAttribute( 'novalidate' );
	}, 100 );

	// Remove header elements to properly show notices.
	document.querySelector( 'h1:not(.mb-header h1)' )?.remove();
	document.querySelector( '.page-title-action' )?.remove();
	document.querySelector( '.wp-header-end' )?.remove();

	form.addEventListener( 'submit', async e => {
		e.preventDefault();

		const submitButton = e.submitter || form.querySelector( '.mb-cpt-submit' );
		if ( !submitButton ) {
			return;
		}

		submitButton.disabled = true;
		const currentText = submitButton.value;
		submitButton.value = MBBModel.saving;

		try {
			const response = await fetcher( {
				api: 'custom-model/save',
				params: {
					post_id: document.querySelector( '#post_ID' ).value,
					post_title: getSettings().labels?.singular_name || getSettings().labels?.name || '',
					settings: getSettings(),
				},
				method: 'POST',
				cache: false,
			} );

			if ( !response.success ) {
				alert( response.message );
				return;
			}

			// Soft success indicator like CPT.
			const existing = document.querySelector( '.mb-cpt-message' );
			existing?.remove();
			const message = document.createElement( 'div' );
			message.className = 'mb-cpt-message';
			message.textContent = response.message || MBBModel.saved;
			document.querySelector( '.mb-header' )?.appendChild( message );
			setTimeout( () => message.remove(), 3000 );
		} catch ( error ) {
			let message = error.message;

			if ( error.data?.details && !Array.isArray( error.data?.details ) ) {
				message = Object.values( error.data?.details ).map( item => item.message ).join( "\n" );
			}

			alert( message );
		} finally {
			submitButton.value = currentText;
			submitButton.disabled = false;
		}
	} );

	document.addEventListener( 'keydown', e => {
		if ( ( e.ctrlKey || e.metaKey ) && e.key === 's' ) {
			e.preventDefault();
			const button = form.querySelector( '.mb-cpt-submit' );
			if ( button && !button.disabled ) {
				button.click();
			}
		}
	} );
};
