import { Flex, Icon, TabPanel, Tooltip } from '@wordpress/components';
import { useContext, useEffect } from "@wordpress/element";
import { __ } from '@wordpress/i18n';
import { code } from "@wordpress/icons";
import { SettingsContext } from './SettingsContext';
import CheckboxList from './controls/CheckboxList';
import Control from './controls/Control';
import { ReactComponent as Logo } from './controls/logo.svg';
import Result from './Result';
import { AdvancedControls, BasicControls, CodeControls, LabelControls, SupportControls } from './constants/Data';
import { initSaveForm } from './save';

const tabs = [
	{
		name: 'general',
		title: __( 'General', 'meta-box-builder' ),
	},
	{
		name: 'labels',
		title: __( 'Labels', 'meta-box-builder' ),
	},
	{
		name: 'advanced',
		title: __( 'Advanced', 'meta-box-builder' ),
	},
	{
		name: 'supports',
		title: __( 'Supports', 'meta-box-builder' ),
	},
	{
		name: 'code',
		icon: <Icon icon={ code } />,
		title: __( 'Get PHP Code', 'meta-box-builder' ),
		className: 'mb-cpt-code components-button is-small has-icon'
	}
];

let autoFills = [ ...LabelControls, ...BasicControls ];
autoFills.push( { name: 'table', updateFrom: 'labels.singular_name' } );

const panels = {
	general: BasicControls.map( ( field, key ) => <Control key={ key } field={ field } autoFills={ autoFills.filter( f => f.updateFrom === field.name ) } /> ),
	labels: LabelControls.map( ( field, key ) => <Control key={ key } field={ field } /> ),
	advanced: AdvancedControls.map( ( field, key ) => <Control key={ key } field={ field } /> ),
	supports: <CheckboxList name="supports" options={ SupportControls } description={ __( 'Features the model supports:', 'meta-box-builder' ) } />,
	code: (
		<>
			{ CodeControls.map( ( field, key ) => <Control key={ key } field={ field } /> ) }
			<Result />
		</>
	)
};

const MainTabs = () => {
	const { settings } = useContext( SettingsContext );

	useEffect( () => {
		initSaveForm( () => settings );
	}, [ settings ] );

	return <>
		<Flex className="mb-header">
			<Flex gap={ 2 } expanded={ false }>
				<Tooltip text={ __( 'Back to all custom models', 'meta-box-builder' ) } position={ 'bottom right' }>
					<a className="mb-header__logo" href={ MBBModel.url }><Logo /></a>
				</Tooltip>
				<h1>{ MBBModel.action === 'add' ? __( 'Add Custom Model', 'meta-box-builder' ) : __( 'Edit Custom Model', 'meta-box-builder' ) }</h1>
			</Flex>
			<Flex gap={ 1 } expanded={ false }>
				<input
					type="submit"
					className="mb-cpt-submit components-button is-primary"
					value={ __( 'Save Changes', 'meta-box-builder' ) }
				/>
			</Flex>
		</Flex>
		<div className="mb-cpt-body mb-body">
			<div className="mb-body__inner">
				<div className="mb-main">
					<div className="wp-header-end" />

					<TabPanel className="mb-box" tabs={ tabs }>
						{ tab => panels[ tab.name ] }
					</TabPanel>
				</div>
			</div>
		</div>
	</>;
};

export default MainTabs;
